final case class Account private (balance: Long, floor: Long)

object Account {
  def open(floor: Long): Account = {
    require(floor >= 0, s"floor must be non-negative: $floor")
    Account(floor, floor)
  }

  def withdraw(a: Account, amount: Long): Account = {
    require(amount > 0, s"amount must be positive: $amount")
    val nextBalance = a.balance - amount
    require(nextBalance >= a.floor, s"withdrawal would break invariant: $nextBalance < ${a.floor}")
    val next = a.copy(balance = nextBalance)
    assert(next.balance >= next.floor, s"invariant: $next")
    next
  }
}
